  86: {
    en: { hook: "Red-green Corroso vase, model no. 4101.", desc: "Red-green Corroso vase, model no. 4101. Design 1936-1938.\nH = 21 cm.\n\"Vaso in vetro corroso rubino et verde con bugne applicate e superficie iridata.\"\nThis model, however only monochrome, was exhibited at the VI Triennale 1936 in Milan.\nOur vase is a rare bicolour version.\nTwo-line etched signature.\nRef: Marino Barovier, Skira 2012, CARLO SCARPA VENINI 1932-1947, P. 214.\nAnna Venini Dias de Santillana, Skira 2000, Venini, Catalogo ragionato 1921-1986, P. 141.\nMarino Barovier, Skira 1999, Carlo Scarpa Glass of an Architect, P. 125 and 211." },
    fr: { hook: "Vase Corroso rouge-vert, modèle n° 4101.", desc: "Vase Corroso rouge-vert, modèle n° 4101. Conception 1936-1938.\nH = 21 cm.\n\"Vaso in vetro corroso rubino et verde con bugne applicate e superficie iridata.\"\nCe modèle, cependant uniquement monochrome, fut exposé à la VI Triennale de Milan en 1936.\nNotre vase est une rare version bicolore.\nSignature gravée sur deux lignes.\nRéf: Marino Barovier, Skira 2012, CARLO SCARPA VENINI 1932-1947, P. 214.\nAnna Venini Dias de Santillana, Skira 2000, Venini, Catalogo ragionato 1921-1986, P. 141.\nMarino Barovier, Skira 1999, Carlo Scarpa Glass of an Architect, P. 125 et 211." },
    it: { hook: "Vaso Corroso rosso-verde, modello n. 4101.", desc: "Vaso Corroso rosso-verde, modello n. 4101. Disegno 1936-1938.\nA = 21 cm.\n\"Vaso in vetro corroso rubino et verde con bugne applicate e superficie iridata.\"\nQuesto modello, tuttavia solo monocromo, fu esposto alla VI Triennale del 1936 a Milano.\nIl nostro vaso è una rara versione bicolore.\nFirma incisa su due righe.\nBibl: Marino Barovier, Skira 2012, CARLO SCARPA VENINI 1932-1947, P. 214.\nAnna Venini Dias de Santillana, Skira 2000, Venini, Catalogo ragionato 1921-1986, P. 141.\nMarino Barovier, Skira 1999, Carlo Scarpa Glass of an Architect, P. 125 e 211." }
  },
