  96: {
    en: { hook: "Transparent, blue-tinted glass.", desc: "Vase after a design by Vittorio Zecchin 1921/22. Transparent, blue-tinted glass. Funnel-shaped vase with disc foot. Model number 1463 at Cappellin and 5017 at MVM. Unmarked.\nH = 18 cm. D = 17.5 cm.\nExhibitions: 1922, Paris Salon d'Automne 1923, Monza, 1st Biennale.\nRef: Marino Barovier & Carla Sonego. SKIRA. Vittorio Zecchin, Transparent Glass for Cappellin and Venini." },
    fr: { hook: "Verre transparent teinté bleu.", desc: "Vase d'après un dessin de Vittorio Zecchin 1921/22. Verre transparent teinté bleu. Vase en forme d'entonnoir avec pied en disque. Numéro de modèle 1463 chez Cappellin et 5017 chez MVM. Non signé.\nH = 18 cm. D = 17,5 cm.\nExpositions: 1922, Paris Salon d'Automne 1923, Monza, 1ère Biennale.\nRéf: Marino Barovier & Carla Sonego. SKIRA. Vittorio Zecchin, Transparent Glass for Cappellin and Venini." },
    it: { hook: "Vetro trasparente colorato blu.", desc: "Vaso da un disegno di Vittorio Zecchin 1921/22. Vetro trasparente colorato blu. Vaso a forma di imbuto con piede a disco. Numero di modello 1463 presso Cappellin e 5017 presso MVM. Non contrassegnato.\nA = 18 cm. D = 17,5 cm.\nEsposizioni: 1922, Parigi Salon d'Automne 1923, Monza, 1ª Biennale.\nBibl: Marino Barovier & Carla Sonego. SKIRA. Vittorio Zecchin, Transparent Glass for Cappellin and Venini." }
  },
